import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID as uid} from 'node:crypto';
import {readFile,writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {fifthDatabase,read,write,type Fifth} from '../support/h5-018-fifth-isolated.ts';
import {providerPaymentFixture} from '../support/h3-provider-payment-fixtures.ts';
import {paymentFixture} from '../support/h3-payment-fixtures.ts';
import {allocationFixture} from '../support/h3-allocation-fixtures.ts';
import {ownEconomicsFixture,syntheticOwnInput,fact} from '../support/h3-own-economics-fixtures.ts';
import {preparationFixture} from '../support/h4-booking-preparation-fixtures.ts';
