let h:Fifth;const traces:Record<string,unknown>={};
before(async()=>{h=await fifthDatabase('h6005_core_'+uid().replaceAll('-','').slice(0,8),61200);});
after(async()=>{if(h){await writeFile(join(process.env.H6005_OUTPUT!,'observed.json'),JSON.stringify(traces,null,2)+'\n');await writeFile(join(process.env.H6005_OUTPUT!,'postgres.log'),await readFile(h.temporary+'/postgres.log'));await h.close();}});
const record=async(id:string,value:unknown)=>{traces[id]=value;};
async function snap(){const rows=await h.observer`select tablename from pg_tables where schemaname='crm_private' and (tablename like 'b05_%' or tablename like 'b06_closure%') order by tablename`;const result:Record<string,unknown>={};for(const r of rows)result[r.tablename]= (await h.observer.unsafe(`select coalesce(jsonb_agg(x order by x::text),'[]') v from(select to_jsonb(t) x from crm_private.${r.tablename} t)z`))[0]!.v;return result;}
test('H6005 C01 AC025/026/028 forecast, detection, receipt, doubt, partial correspondence, duplicate and distinct transfer',async()=>{
 const f=await paymentFixture(h,'500.00',true,'1000.00');assert.equal(await h.payments.read(await h.auth(),read,f.paymentId),null);
 await h.payments.apply(await h.auth(),write,f.detect);let s=(await h.payments.read(await h.auth(),read,f.paymentId))!;await record('C01-detected',s);assert.equal(s.summary.grossReceived,'0.00');
 assert.equal((await h.payments.apply(await h.auth(),write,f.detect)).replayed,true);
 await h.payments.apply(await h.auth(),write,await f.receive());const p=await f.propose(2,'200.00');await h.payments.apply(await h.auth(),write,p);s=(await h.payments.read(await h.auth(),read,f.paymentId))!;await record('C01-proposed',s);
 assert.equal(s.summary.grossReceived,'500.00');assert.equal(s.summary.verified,'0.00');
 await h.payments.apply(await h.auth(),write,await f.verify(p));s=(await h.payments.read(await h.auth(),read,f.paymentId))!;assert.equal(s.summary.verified,'200.00');await record('C01-verified200-pending300',s);
 const other=await paymentFixture(h,'500.00',true,'1000.00');await h.payments.apply(await h.auth(),write,other.detect);await h.payments.apply(await h.auth(),write,await other.receive());assert.notEqual(other.identity.externalId,f.identity.externalId);assert.equal((await h.payments.read(await h.auth(),read,other.paymentId))!.summary.grossReceived,'500.00');
});
test('H6005 C02 E2E05 continuous500managed100fee paid before client invoice, later reviewed link, independent own margin, discrepancy',async t=>{
 const observed:unknown[]=[];const payments={...h.payments,apply:async(...args:Parameters<typeof h.payments.apply>)=>{const v=await h.payments.apply(...args);observed.push({action:args[2].action,view:await h.payments.read(await h.auth(),read,args[2].paymentId)});return v;}};
 const f=await providerPaymentFixture({...h,payments} as Fifth,'700.00','500.00');await record('C02-transfer-receipt-correspondence',observed);await h.providerPayments.apply(await h.auth(),write,await f.open());
 const a=await f.assign('500.00');const fee=await f.su.assign('100.00','500.00','fee');let funds=await f.su.funds.see();assert.equal(funds.summary.assigned,'600.00');assert.equal((funds.summary.byPurpose as any).managed_client_funds.assigned,'500.00');assert.equal((funds.summary.byPurpose as any).fee.assigned,'100.00');assert.equal(funds.summary.consumed,'0.00');
 await h.suplidos.apply(await h.auth(),write,await f.su.command('evaluate'));assert.equal((await f.su.see())!.components.mandate,null);const beforeWrong=await f.su.see();await assert.rejects(h.suplidos.apply(await h.auth(),write,await f.su.fundsCommand([fee.allocationId!])));assert.deepEqual(await f.su.see(),beforeWrong);
 const schedule=await f.schedule([await f.portion(a)]);await assert.rejects(h.providerPayments.apply(await h.auth(),write,schedule));await(await f.approval(schedule)).execute();assert.equal((await f.view())!.paid,'0.00');
 const movement=await f.movement([await f.portion(a)],'500.00');await h.providerPayments.apply(await h.auth(),write,movement);assert.equal((await f.view())!.paid,'500.00');assert.equal((await f.su.see())!.status,'Gestión abierta');assert.ok((await f.su.see())!.pending.includes('invoice'));assert.equal((await f.su.funds.see()).summary.consumed,'500.00');await record('C02-paid500-before-invoice',{payment:await f.view(),suplido:await f.su.see(),funds:await f.su.funds.see()});
 const before=await snap();assert.equal((await h.providerPayments.apply(await h.auth(),write,movement)).replayed,true);assert.deepEqual(await snap(),before);
 const c=await closureCommands(h,f.su.bookingId);await c.run(await c.command('economic',{}, {serviceApplicability:[{serviceId:f.basis.serviceId,suplido:true,deposit:false,ownEconomics:true,reason:'SYNTHETIC managed500 and own100 distinct obligations'}]}));assert.equal((await c.view()).assessments.economic!.criteria.find(x=>x.id==='supplier-documents')!.result,'pending');
 await h.suplidos.apply(await h.auth(),write,await f.su.attachInvoice(2));assert.equal((await h.invoices.read(await h.auth(),read,f.su.invoice.invoiceId,f.su.bookingId))!.status,'Recibida');assert.equal((await f.view())!.paid,'500.00');
 const inv=f.su.invoice;await h.invoices.apply(await h.auth(),write,await inv.attest({...await inv.review(),bookingId:f.su.bookingId,expectedRevision:2}));await h.invoices.apply(await h.auth(),write,await inv.attest({...await inv.link(),bookingId:f.su.bookingId,expectedRevision:3,portions:[{serviceId:f.basis.serviceId,amount:'500.00',sourceRef:'SYNTHETIC exact provider service attribution'}]}));await h.suplidos.apply(await h.auth(),write,await f.su.command('component',{component:'invoice',invoiceId:inv.invoiceId}));await h.suplidos.apply(await h.auth(),write,await f.su.command('evaluate'));assert.equal((await f.su.see())!.status,'Documentalmente resuelto');assert.equal((await f.su.see())!.evaluation!.fiscalValidation,false);
 const unit=await h.cat('unit',{name:'SYNTHETIC own fixed',definition:'fixed group'}),form=await h.cat('pricing_form',{name:'SYNTHETIC fixed',definition:'fixed'}),economyId=uid(),input=structuredClone(syntheticOwnInput());
 const proof=async(claim:string)=>f.su.funds.proof(economyId,claim);const hash=async(x:unknown)=>(await h.observer`select encode(crm_crypto.digest(convert_to(${JSON.stringify(x)}::text::jsonb::text,'UTF8'),'sha256'),'hex') h`)[0]!.h;
 for(const x of [...input.fees,...input.costs]){Object.assign(x,{serviceId:f.basis.serviceId,unitRevisionId:unit.revision,pricingFormRevisionId:form.revision});const {approvalEvidenceId,...rule}=x.rule;Object.assign(x.rule,{approvalEvidenceId:await proof('own-rule:'+await hash(rule))});}
 const material={economyId,bookingId:f.su.bookingId,scope:'SYNTHETIC own fee100 cost20, distinct500managed',expectedRevision:0,expectedBookingRevision:1,at:new Date().toISOString(),sourceRef:'SYNTHETIC approved exact own facts',reason:'SYNTHETIC separation own/managed',input};const q={...material,operationId:uid(),evidenceId:await proof('own-economics:'+await hash(material))};await h.ownEconomics.apply(await h.auth(),write,q);const own=(await h.ownEconomics.read(await h.auth(),read,economyId,f.su.bookingId))!;assert.equal(own.computed.totals.real.profit,'80.00');assert.equal(own.computed.totals.real.fee,'100.00');assert.equal(own.computed.totals.real.cost,'20.00');assert.equal(own.computed.fiscalValidation,false);assert.equal(own.computed.mandateInferred,false);
 await c.run(await c.command('economic',{}, {action:'evaluate',serviceApplicability:[{serviceId:f.basis.serviceId,suplido:true,deposit:false,ownEconomics:true,reason:'SYNTHETIC real independently attributed facts'}]}));assert.equal((await c.view()).assessments.economic!.criteria.find(x=>x.id==='supplier-documents')!.result,'satisfied');assert.equal((await c.view()).jointClosure.current,false);await record('C02-documentary-resolved-own80',{payment:await f.view(),suplido:await f.su.see(),funds:await f.su.funds.see(),own,closure:await c.view()});
 await h.suplidos.apply(await h.auth(),write,await f.su.command('discrepancy',{component:'invoice',incidentId:uid()}));await h.suplidos.apply(await h.auth(),write,await f.su.command('evaluate'));assert.equal((await f.su.see())!.status,'Gestión abierta');assert.equal((await f.view())!.paid,'500.00');await record('C02-new-discrepancy',await f.su.see());
});
test('H6005 C03 AC023 critical and 50percent at10days; missing critical, unverified and6days50 reject confirmation',async()=>{
 for(const [days,critical,stage,amount,expected] of [[10,true,'assign','500.00','Confirmada operativamente'],[10,false,'assign','500.00','En confirmación con proveedores'],[10,true,'propose','500.00','Parcialmente confirmada'],[6,true,'assign','500.00','Parcialmente confirmada'],[6,true,'assign','1000.00','Confirmada operativamente']] as const){const f=await preparationFixture(h,days);if(critical)await f.confirm();await f.pay(amount,stage);const r=await f.run(await f.command());assert.equal(r.result.phase,expected);await record(`C03-${days}-${critical}-${stage}-${amount}`,r.result);}
});
test('H6005 C04 AC027 race80+80 over100 and failed second operation preserves only80',async()=>{
 const f=await allocationFixture(h,'100.00','100.00','verified','1000.00'),a=await f.assign('80.00'),b=await f.assign('80.00');const r=await Promise.allSettled([h.allocations.apply(await h.auth(),write,a),h.allocations.apply(await h.auth(),write,b)]);assert.equal(r.filter(x=>x.status==='fulfilled').length,1);assert.equal((await f.see()).summary.assigned,'80.00');await record('C04-race',{outcomes:r.map(x=>x.status),funds:await f.see()});
});
test('H6005 C05 AC035 refund right200 paid80 leaves120; withdrawal no execution',async()=>{
 const f=await refundFixture(h);await f.run(await f.request());await f.run(await f.determine());await(await f.approval(await f.authorization())).execute();const q=await f.movement('80.00');await f.run(q);assert.equal((await f.view())!.executed,'80.00');assert.equal((await f.view())!.pendingRight,'120.00');const snapshot=await f.view();assert.equal((await f.run(q)).replayed,true);assert.deepEqual(await f.view(),snapshot);await f.run(await f.command('withdraw'));assert.equal((await f.view())!.executed,'80.00');assert.equal((await f.view())!.pendingRight,'120.00');await record('C05',await f.view());
});
test('H6005 C06 AC036 guarantee custody100 retained20, return80 completed only by actual fact and canonical Refund',async()=>{
 const f=await depositFixture(h);await f.initialize();await f.run(await f.delivery());await f.run(await f.evaluate());await(await f.approval(await f.determination())).execute();await f.run(await f.fact('retain','20.00','0.00'));assert.equal((await f.view()).amounts.pendingReturn,'80.00');const c=await closureCommands(h,f.bid);await c.run(await c.command('economic'));assert.equal((await c.view()).assessments.economic!.criteria.find(x=>x.id==='deposits')!.result,'pending');const q=await f.fact('return','80.00','20.00');await f.run(q);assert.equal((await f.view()).amounts.pendingReturn,'0.00');assert.equal((await f.view()).amounts.returned,'80.00');assert.equal((await f.run(q)).replayed,true);const d=await f.view(),refund=await h.refunds.read(await h.auth(),read,f.bid,d.refundId);assert.equal(refund!.executed,'80.00');await record('C06',{deposit:d,refund});
});
test('H6005 C07 AC047–049 Tarari internal15/3.80 +175/325, unknown real cost and VAT; forbidden external records',async()=>{
 const f=await ownEconomicsFixture(h),q:any=await f.command();q.input.tarari=['included2','extra25','extra50'].map((kind,i)=>({id:'SYNTHETIC-'+i,serviceId:f.b.detail.services[0]!.id,unitRevisionId:f.unit.revision,pricingFormRevisionId:f.form.revision,kind})) as typeof q.input.tarari;await h.ownEconomics.apply(await h.auth(),write,await f.attest(q));const s=(await f.see())!;assert.deepEqual(s.computed.tarari.map(x=>x.commercial),['15.00','175.00','325.00']);assert.deepEqual(s.computed.tarari.map(x=>x.cost),['3.80',null,null]);assert.equal(s.computed.totals.real.profit,null);for(const x of s.computed.tarari){assert.equal(x.provider,null);assert.equal(x.suplido,null);assert.equal(x.internalInvoice,null);}assert.equal(s.computed.costs[0]!.phases.real.fact.vat,'unknown');assert.equal(s.computed.costs[0]!.phases.real.fact.tax,null);
 const tableCounts=async()=>{const result:Record<string,number>={};for(const table of ['b05_provider_invoices','b05_suplidos','b05_provider_payments'])result[table]=(await h.observer.unsafe(`select count(*)::int n from crm_private.${table} where booking_id=$1`,[f.bookingId]))[0]!.n;return result;};assert.deepEqual(await tableCounts(),{b05_provider_invoices:0,b05_suplidos:0,b05_provider_payments:0});await record('C07',{economics:s,counts:await tableCounts()});
});
test('H6005 C08 scope/evidence/auth denial, immutable product histories and direct fiscal attributes denied',async()=>{
 const f=await providerPaymentFixture(h);await h.providerPayments.apply(await h.auth(),write,await f.open());const q=await f.command('confirm',{confirmedAmount:'500.00'}),before=await f.view();const alien=await verifyAuth({verify:async()=>({subject:uid(),sessionId:uid(),passwordVerified:true,mfaVerified:true})},uid());await assert.rejects(h.providerPayments.apply(alien,write,q));await assert.rejects(h.providerPayments.read(alien,read,f.id,f.su.bookingId));await assert.rejects(h.providerPayments.apply(await h.auth(),read,q));await assert.rejects(h.providerPayments.apply(await h.auth(),write,await f.attest({...q,bookingId:uid()})));await assert.rejects(h.providerPayments.apply(await h.auth(),write,{...q,evidenceId:uid()}));for(const field of ['ownIncome','ownCost','fiscalNumber','invoiceIssued'])await assert.rejects(h.providerPayments.apply(await h.auth(),write,await f.attest({...q,[field]:true})));assert.deepEqual(await f.view(),before);await assert.rejects(h.runtime.unsafe('select * from crm_private.b05_provider_payment_revisions'));await assert.rejects(h.admin.unsafe('update crm_private.b05_provider_payment_revisions set admin_scope=admin_scope'));await record('C08',{denials:10,history:(await f.view())!.history});
});
test('H6005 C09 T07 injected deferred failure rolls back shared funds and provider/related histories, retry, lost response durable replay',async()=>{
 const f=await providerPaymentFixture(h);await h.providerPayments.apply(await h.auth(),write,await f.open());const a=await f.assign();await(await f.approval(await f.schedule([await f.portion(a)]))).execute();const q=await f.movement([await f.portion(a)],'500.00'),before=await snap();await h.admin.unsafe("create function crm_private.h6005_fault()returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_H6005_COMMIT_FAULT';end$$");await h.admin.unsafe('create constraint trigger h6005_fault after insert on crm_private.b05_provider_payment_operations deferrable initially deferred for each row execute function crm_private.h6005_fault()');try{await assert.rejects(h.providerPayments.apply(await h.auth(),write,q));assert.deepEqual(await snap(),before);}finally{await h.admin.unsafe('drop trigger h6005_fault on crm_private.b05_provider_payment_operations;drop function crm_private.h6005_fault()');}
 const lost={begin:async(o:any,w:any)=>{await h.runtime.begin(o,w);throw Error('SYNTHETIC_RESPONSE_LOST_AFTER_COMMIT');}} as unknown as typeof h.runtime;await assert.rejects(new H3011ProviderPaymentAdapter(lost,h.f1,h.f2).apply(await h.auth(),write,q),/RESPONSE_LOST/);assert.equal((await f.view())!.paid,'500.00');const after=await snap();assert.equal((await h.providerPayments.apply(await h.auth(),write,q)).replayed,true);assert.deepEqual(await snap(),after);await record('C09',{provider:await f.view(),funds:await f.su.funds.see()});
});
